using System;
class Program {static void Main(){int n=0;void Check(bool ok,string message){n++;if(!ok)throw new Exception(message);}Check(RebirthPoiSleeperShapePolicy.FlagsMatch(19,3),"native saved script data must not reject completed substation room");Check(RebirthPoiSleeperShapePolicy.FlagsMatch(3,19),"script-data bit can clear on save");for(int authored=0;authored<256;authored++){Check(RebirthPoiSleeperShapePolicy.FlagsMatch(authored,authored),"unchanged");Check(RebirthPoiSleeperShapePolicy.FlagsMatch(authored^16,authored),"only serialization toggles");for(int bit=0;bit<31;bit++){if(bit==4)continue;Check(!RebirthPoiSleeperShapePolicy.FlagsMatch(authored^(1<<bit),authored),"changed gameplay bit "+bit);}}Console.WriteLine("PASS "+n+" actual production flag-policy checks; native clearance still required.");}}
